import * as React from 'react'
import { cn } from '@/lib/utils'
import { useMergedRefs } from '@/lib/merge-refs'
import { COMPACT_CONTROL_HEIGHT, compactControlClass } from '@/lib/compact-control'

export interface SegmentedControlOption<T extends string = string> {
  value: T
  label: string
  /**
   * Optional element rendered BEFORE the label, on the same line. The DS bundles
   * no icon library, so the caller passes the node: usually a Phosphor glyph,
   * but anything works -- Icon Stack passes a thumbnail of the image each
   * segment selects, because "Main" and "Alternate" say nothing about which
   * artwork you are choosing.
   */
  icon?: React.ReactNode
}

export interface SegmentedControlProps<T extends string = string> {
  options: SegmentedControlOption<T>[]
  value: T
  onChange: (value: T) => void
  /** Accessible name for the group. */
  'aria-label'?: string
  /**
   * Render the icons alone, with each option's `label` becoming its accessible
   * name and its tooltip rather than visible text.
   *
   * For the case where a pair of glyphs IS the vocabulary -- a sun and a moon, a
   * contain and a cover arrow -- and spelling it out costs more room than it
   * earns. It is all-or-nothing on purpose: a strip mixing labelled and bare
   * segments reads as one of them having failed to render.
   *
   * `label` stays required, because an icon-only control still has to say what it
   * is. Each segment gets both `aria-label` and `title` from it, per the
   * accessibility rule for icon-only controls.
   */
  hideLabels?: boolean
  className?: string
}

/**
 * Compact pick-one control: one bordered strip, divided into segments.
 *
 * ## Why this is not a size variant of `ToggleGroup`
 *
 * `ToggleGroup` is a grid of separate tiles, each bordered, icon stacked above
 * the label, sized to be the primary choice on a settings screen. This is a
 * single bordered strip with internal dividers, icon beside the label, sized to
 * sit ON A LINE with body text as the trailing control of a labelled row.
 *
 * Those are two constructions, not two sizes. A `size="sm"` on `ToggleGroup`
 * would have to change the border from per-tile to per-group, the icon from
 * stacked to inline, and the layout from a gap-separated grid to a joined strip
 * -- at which point the only thing the two share is the word "toggle". Keeping
 * them separate means each stays legible on its own terms.
 *
 * What they DO share is behaviour, and that is deliberate: same `radiogroup`
 * role, same roving `tabIndex`, same arrow-key wrap-around, same accent fill on
 * the selected option. A control that looks different should not also *act*
 * different, so the keyboard model here is `ToggleGroup`'s, and a test pins the
 * two against each other.
 *
 * Reach for `ToggleGroup` when the choice is the point of the screen, and this
 * when the choice is one row among many.
 *
 * ```tsx
 * <SegmentedControl
 *   aria-label={t('source.fit')}
 *   options={[
 *     { value: 'contain', label: t('source.contain'), icon: <ArrowsIn size={14} /> },
 *     { value: 'cover', label: t('source.cover'), icon: <ArrowsOut size={14} /> },
 *   ]}
 *   value={fit}
 *   onChange={setFit}
 * />
 * ```
 */
function SegmentedControlInner<T extends string = string>(
  { options, value, onChange, hideLabels, className, ...rest }: SegmentedControlProps<T>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const mergedRef = useMergedRefs(containerRef, ref)

  // Deliberately identical to ToggleGroup's: both are single-select radiogroups,
  // and a user who learns one should not have to relearn the other.
  const handleKeyDown = React.useCallback(
    (e: React.KeyboardEvent<HTMLDivElement>) => {
      if (!options.length) return
      const currentIndex = options.findIndex((o) => o.value === value)

      let nextIndex: number | null = null
      if (e.key === 'ArrowRight' || e.key === 'ArrowDown') {
        nextIndex = currentIndex < options.length - 1 ? currentIndex + 1 : 0
      } else if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
        nextIndex = currentIndex > 0 ? currentIndex - 1 : options.length - 1
      }

      if (nextIndex !== null) {
        e.preventDefault()
        const next = options[nextIndex]
        onChange(next.value as T)
        const btn = containerRef.current?.querySelectorAll<HTMLElement>('[role="radio"]')[nextIndex]
        btn?.focus()
      }
    },
    [options, value, onChange],
  )

  return (
    <div
      ref={mergedRef}
      role="radiogroup"
      onKeyDown={handleKeyDown}
      // `inline-flex` so the strip is as wide as its content and can sit at the
      // end of a row rather than filling it, which is the whole point of it.
      className={cn(
        'inline-flex items-center overflow-hidden rounded-lg border',
        // The height lives here rather than in the segments' padding, so a size
        // chip or a toggle pill built from `compactControlClass` matches it
        // exactly instead of approximately.
        COMPACT_CONTROL_HEIGHT,
        'border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
        className,
      )}
      {...rest}
    >
      {options.map((option, index) => {
        const isSelected = value === option.value
        return (
          <button
            key={option.value}
            role="radio"
            aria-checked={isSelected}
            tabIndex={isSelected ? 0 : -1}
            type="button"
            onClick={() => onChange(option.value as T)}
            // Both, per the icon-only rule: aria-label names it for assistive
            // tech, title for a sighted user who cannot read the glyph.
            {...(hideLabels ? { 'aria-label': option.label, title: option.label } : null)}
            className={cn(
              compactControlClass({ inset: true }),
              // Square-ish when there is no text to give the segment width.
              hideLabels && '!px-2',
              // Dividers belong to the segments rather than the container, so a
              // one-option control has no stray rule down its side.
              index > 0 && 'border-s border-[var(--color-border-light)] dark:border-[var(--color-border-dark)]',
              isSelected
                ? 'bg-[var(--color-accent-500)] text-[var(--color-accent-foreground)]'
                : [
                    'bg-[var(--color-surface-light)] text-[var(--color-text-secondary-light)]',
                    'hover:bg-[var(--color-warm-100)]',
                    'dark:bg-[var(--color-surface-dark)] dark:text-[var(--color-text-secondary-dark)]',
                    'dark:hover:bg-[var(--color-neutral-800)]',
                  ],
            )}
          >
            {option.icon && (
              <span aria-hidden className="flex shrink-0 items-center">
                {option.icon}
              </span>
            )}
            {!hideLabels && option.label}
          </button>
        )
      })}
    </div>
  )
}

export const SegmentedControl = React.forwardRef(SegmentedControlInner) as <
  T extends string = string,
>(
  props: SegmentedControlProps<T> & { ref?: React.ForwardedRef<HTMLDivElement> },
) => React.ReactElement
